151	// ── H1: the footer after a refused ctrl+r ───────────────────────────────────
152	
153	func TestTheFooterAfterARefusedRefreshExplainsAndStaysAWarning(t *testing.T) {
154		for _, tc := range []struct {
155			name  string
156			err   error
157			words []string
158		}{
159			{"account 403", refusalOf(403, false), []string{"could not be read", "this account", "repo_prefix"}},
160			{"account 401", refusalOf(401, false), []string{"could not be read", "this account", "repo_prefix"}},
161			{"anonymous", refusalOf(403, true), []string{"repo_prefix"}},
162		} {
163			t.Run(tc.name, func(t *testing.T) {
164				m := groupModel(t)
165				m = feed(t, m, RegistryGroupDetectedMsg{RegistryURL: registryHostInTest, Slug: "prod", Err: tc.err, At: at(7)})
166	
167				if m.footer.Level() != sharedcomponents.LevelWarning {
168					t.Errorf("footer level = %v, want Warn (%q)", m.footer.Level(), m.footer.Text())
169				}
170				wantAll(t, "footer", m.footer.Text(), tc.words...)
171				wantRefusalText(t, "footer", m.footer.Text())
172				if strings.Contains(m.footer.Text(), tc.err.Error()) {
173					t.Errorf("footer = %q carries the error text", m.footer.Text())
174				}
175			})
176		}
177	}
