179	// ── H2/H3 through the model ─────────────────────────────────────────────────
180	
181	func listing(members int, day int) *cache.RegistryGroupEntry {
182		e := cache.RegistryGroupEntry{DiscoveredAt: at(day)}
183		for i := range members {
184			e.Members = append(e.Members, cache.RegistryGroupMember{
185				Alias: fmt.Sprintf("m%d", i), URL: registryHostInTest, RepoPrefix: fmt.Sprintf("m%d", i),
186			})
187		}
188		return &e
189	}
