214	func TestTheMembersCellOfEachState(t *testing.T) {
215		cases := []struct {
216			name    string
217			entry   *cache.RegistryGroupEntry
218			refusal *cache.RegistryGroupRefusal
219			want    func(cell string) string // empty string = pass, else the complaint
220		}{
221			{"never probed", nil, nil, exactly("never")},
222			{"listed", listing(2, 3), nil, exactly("2 · " + theme.TimeAgo(at(3)))},
223			{"settled empty", listing(0, 3), nil, exactly("0 · " + theme.TimeAgo(at(3)))},
224			{"refused, never listed", nil, refusalAt(7), exactly("denied · " + theme.TimeAgo(at(7)))},
225			{"refused after an empty listing", listing(0, 3), refusalAt(7), exactly("denied · " + theme.TimeAgo(at(7)))},
226			{"refused, 2 members known", listing(2, 3), refusalAt(7), func(c string) string {
227				if !strings.HasPrefix(c, "denied") || !strings.Contains(c, "2 known") || !strings.Contains(c, theme.TimeAgo(at(7))) {
228					return "want denied first, the 2 members known and the age of the refusal"
229				}
230				return ""
231			}},
232			{"stale refusal, listing is newer", listing(2, 9), refusalAt(7), exactly("2 · " + theme.TimeAgo(at(9)))},
233		}
234		for _, tc := range cases {
235			t.Run(tc.name, func(t *testing.T) {
236				m := tabWith(t, testConfig(), tc.entry, tc.refusal)
237				cell := m.registryTable.Table().Rows()[0][membersCol]
238	
239				if complaint := tc.want(cell); complaint != "" {
240					t.Errorf("Members cell = %q: %s", cell, complaint)
241				}
242				if strings.Contains(cell, "\x1b") {
243					t.Errorf("Members cell = %q carries an escape sequence (Rule 122)", cell)
244				}
245				// The column must be wide enough to hold the whole word and age.
246				if line := ansi.Strip(renderedRow(t, m.registryTable.View(), "prod")); !strings.Contains(line, cell) {
247					t.Errorf("the rendered row does not hold the whole cell %q:\n%s", cell, line)
248				}
249			})
250		}
251	}
252	
253	func exactly(want string) func(string) string {
254		return func(got string) string {
255			if got != want {
256				return fmt.Sprintf("want %q", want)
257			}
258			return ""
259		}
260	}
