89	// ── The pure wording (H2, H3, H4) ───────────────────────────────────────────
90	
91	func TestRefusedMembersCellSaysDeniedAndWhen(t *testing.T) {
92		for _, tc := range refusalCases {
93			t.Run(tc.name, func(t *testing.T) {
94				ago := theme.TimeAgo(tc.refusal.At)
95	
96				got := refusedMembersCell(groupRefusalView{Refusal: tc.refusal})
97				if want := "denied · " + ago; got != want {
98					t.Errorf("nothing listed: cell = %q, want %q", got, want)
99				}
100				wantRefusalText(t, "cell", got)
101	
102				got = refusedMembersCell(groupRefusalView{Refusal: tc.refusal, Known: 3})
103				if !strings.HasPrefix(got, "denied") {
104					t.Errorf("3 known: cell = %q, want the state first", got)
105				}
106				wantAll(t, "3 known: cell", got, "3 known", ago)
107				wantRefusalText(t, "cell", got)
108			})
109		}
110	}
