112	func TestRefusedStatusLineWording(t *testing.T) {
113		for _, tc := range refusalCases {
114			t.Run(tc.name, func(t *testing.T) {
115				none := refusedStatusLine(groupRefusalView{Refusal: tc.refusal})
116				declared := refusedStatusLine(groupRefusalView{Refusal: tc.refusal, Declared: 2})
117				wantAll(t, "status line", none, "repo_prefix")
118				wantRefusalText(t, "status line", none)
119				wantRefusalText(t, "status line (declared)", declared)
120				if !tc.refusal.Anonymous {
121					if none != statusRefusedLine {
122						t.Errorf("status line = %q, want %q", none, statusRefusedLine)
123					}
124					if want := fmt.Sprintf(statusDeclaredFmt, 2); declared != want {
125						t.Errorf("status line with 2 declared = %q, want %q", declared, want)
126					}
127				}
128				if declared == none {
129					t.Error("declared members must change the line: it says they are used")
130				}
131			})
132		}
133	}
