402	// registryRef is what an entry is displayed as: its address, not its URL.
403	//
404	// The prefix has to be on screen or the tab says nothing useful — one line per
405	// proxy is one host repeated, and a group's members all answer to the same host
406	// too (§3.18). Joined with a slash because that is exactly the head of the pull
407	// reference: `docker pull nexus.example.com/dhi-io-proxy/eclipse-temurin:21`.
408	// Plain text only — Rule 122.
409	func registryRef(url, repoPrefix string) string {
410		if repoPrefix == "" {
411			return url
412		}
413		return strings.TrimSuffix(url, "/") + "/" + repoPrefix
414	}
