416	// membersCell reports what the last discovery for a group found, and when.
417	//
418	// The "when" is not decoration: a cache with no visible age is worse than the
419	// re-detection it replaced, because it looks current whatever it holds
420	// (§3.8, decision 3). Plain text only — Rule 122.
421	func (m *Model) membersCell(reg config.RegistryItem) string {
422		if reg.Kind != config.KindGroup {
423			return ""
424		}
425		if m.refreshingGroups[reg.Slug] {
426			// Static text: the row's dot is the animation (Rule 122).
427			return "refreshing"
428		}
429		if v, ok := m.groupRefusal(reg.Slug); ok {
430			return refusedMembersCell(v)
431		}
432		entry, ok := m.groupCache[reg.Slug]
433		if !ok {
434			return "never" // declared a group, never asked
435		}
436		return fmt.Sprintf("%d · %s", len(entry.Members), timeAgo(entry.DiscoveredAt))
437	}
